"""Refresh only public standings: never reissue CSRF cookies or replace driver forms."""
SCRIPT = r'''<script>
(()=>{let busy=false;const targets=['rally-classification','rally-stage-results','rally-recovery-warning'];async function refresh(){if(busy||document.hidden)return;busy=true;try{const response=await fetch('/api/results/'+encodeURIComponent(location.pathname.split('/').pop()),{credentials:'same-origin',cache:'no-store'});if(!response.ok)return;const doc=new DOMParser().parseFromString(await response.text(),'text/html');for(const id of targets){const old=document.getElementById(id),fresh=doc.getElementById(id);if(!old||!fresh)continue;if(id==='rally-classification'){const before=old.querySelector('.table-scroll'),after=fresh.querySelector('.table-scroll');if(before&&after)before.replaceWith(document.importNode(after,true));continue}const opened=[...old.querySelectorAll('details')].map(x=>x.open);const copy=document.importNode(fresh,true);[...copy.querySelectorAll('details')].forEach((x,i)=>x.open=opened[i]||false);old.replaceWith(copy)}const input=document.getElementById('driver-search');if(input)input.dispatchEvent(new Event('input'));}catch(_){}finally{busy=false}}setInterval(refresh,5000);})();
</script>'''
